package pzvrphysicality;

import java.lang.ref.WeakReference;import java.util.*;import local.pzvr.*;import viewpoint.core.Frame;import viewpointvr.physics.CollisionShape;import viewpointvr.physics.RigidPhysics;import zombie.characters.IsoPlayer;import zombie.inventory.InventoryItem;

/** Contact-only prop ownership. Native equipment, model matrices, actions and controller input remain authoritative. */
public final class HeldContactDriver {
 interface World extends AutoCloseable {void environment(Collection<PhysicalWorld.Static> geometry);boolean target(InventoryItem item,CollisionShape shape,float[] target,float mass);void retain(Collection<InventoryItem> items);void step();HeldContactWorld.Response response(InventoryItem item);void close();}
 interface Factory {void load()throws Exception;World create(double x,double y,double z);}
 private static final Factory nativeFactory=new Factory(){public void load()throws Exception{RigidPhysics.loadDefault();}public World create(double x,double y,double z){var world=new HeldContactWorld<InventoryItem>(x,y,z);return new World(){public void environment(Collection<PhysicalWorld.Static> geometry){world.environment(geometry);}public boolean target(InventoryItem item,CollisionShape shape,float[] target,float mass){return world.target(item,shape,target,mass);}public void retain(Collection<InventoryItem> items){world.retain(items);}public void step(){world.step();}public HeldContactWorld.Response response(InventoryItem item){return world.response(item);}public void close(){world.close();}};}};
 private record Environment(IsoPlayer actor,long rigGeneration,long epoch,long time,List<PhysicalWorld.Static> values){Environment{values=List.copyOf(values);}}
 private record Lease(HeldContactCapture.Sample sample,CollisionShape shape,HeldContactWorld.Response response){}
 private record PackLease(HeldContactExternal.Offer offer,HeldContactWorld.Response response){}
 private record Continuation(HeldContactExternal.Source source,long version,WeakReference<IsoPlayer> actor,WeakReference<Object> cell,int side,long rigGeneration,long sourceEpoch,long time,double units,float mass,Object geometry,CollisionShape shape){}
 private static final IdentityHashMap<InventoryItem,Continuation> continuations=new IdentityHashMap<>();
 private static final FurnitureContacts furniture=new FurnitureContacts();private static Factory factory=nativeFactory;private static volatile boolean enabled;private static double intensity=1,maximum=.04;private static boolean visual=true;private static Frame processedFrame;private static XrBackend.Frame processedInput;private static long processedReceipt=Long.MIN_VALUE,processedEpoch=-1,processedExternal=-1;private static long epoch=1,nextEnvironment,lastStep,lastPulse;private static volatile Environment environment;private static IsoPlayer actor;private static long rigGeneration=-1;private static World world;private static Thread worldOwner;private static boolean closeRequested;private static final IdentityHashMap<InventoryItem,Lease> leases=new IdentityHashMap<>();private static final IdentityHashMap<InventoryItem,PackLease> packLeases=new IdentityHashMap<>();private static String detail="Held prop contacts Off";
 public static synchronized void configure(boolean value)throws Exception{if(value){if(!Main.ready())throw new IllegalStateException("SDK validation pending");factory.load();}if(enabled!=value){enabled=value;epoch++;environment=null;nextEnvironment=lastStep=lastPulse=0;leases.clear();packLeases.clear();continuations.clear();HeldContactExternal.clear();HeldContactCapture.clear();closeRequested=true;try{closeOwned();}catch(RuntimeException|LinkageError failure){enabled=false;epoch++;WorldRigCapture.requestHeldContacts(false);detail="Held contacts disabled after configuration cleanup failure";throw failure;}}WorldRigCapture.requestHeldContacts(value);detail=value?"Supported rigid prop contact feedback armed":"Held prop contacts Off";}
 public static synchronized void configure(boolean value,double density)throws Exception{validIntensity(density);configure(value);intensity=density;}
 public static synchronized void intensity(double density){validIntensity(density);intensity=density;}
 public static synchronized double intensity(){return intensity;}
 public static synchronized void visualConstraints(boolean value,double metres){if(!Double.isFinite(metres)||metres<.01||metres>.08)throw new IllegalArgumentException("Held visual correction .01..08 m");if(visual!=value||maximum!=metres){visual=value;maximum=metres;epoch++;environment=null;nextEnvironment=0;retire("Held visual preference changed");}}
 public static synchronized boolean visualConstraints(){return visual;}public static synchronized double maxCorrection(){return maximum;}static synchronized long epoch(){return epoch;}private static boolean needsSimulation(){return visual||intensity>0&&Engine.settings!=null&&Engine.settings.haptics;}private static boolean semanticBusy(){return NativeConsumption.request()!=null||NativeConsumption.bite()!=null||NativeTaps.busy()||NativeCrafting.request()!=null||NativeBody.request()!=null||BackpackContents.request()!=null||NativeItems.request()!=null;}
 private static void validIntensity(double value){if(!Double.isFinite(value)||value<0||value>1)throw new IllegalArgumentException("Held contact intensity 0..1");}
 public static boolean enabled(){return enabled;}public static synchronized String status(){return detail+"; exact external-held contacts "+packLeases.size()+"; "+HeldContactCapture.status()+"; "+furniture.status();}
 private static IsoPlayer player(){return IsoPlayer.players.length==0?null:IsoPlayer.players[0];}
 private static boolean context(IsoPlayer p,long now){var rig=WorldRigCapture.latest;var input=Engine.latestInput;return enabled&&Main.ready()&&p!=null&&p==player()&&!p.isDead()&&p.getVehicle()==null&&p.getSquare()!=null&&p.getCell()!=null&&!p.hasTimedActions()&&Engine.active()&&Engine.worldPresent&&!zombie.network.GameClient.client&&!zombie.network.GameServer.server&&!zombie.GameTime.isGamePaused()&&!VrApi.fullHud()&&!VrApi.pointerActive()&&!zombie.ui.UIManager.isModalVisible()&&!zombie.core.Core.getInstance().isDoingTextEntry()&&NativeItems.supportsPhysicalGestures(p)&&!semanticBusy()&&rig!=null&&rig.actor()==p&&rig.fresh(now)&&input!=null&&input.focused()&&input.head()!=null&&input.time()==rig.inputTime();}
 /** The same lifecycle, input priority and environment gate used by owned contact transactions. */
 public static synchronized boolean admits(Frame frame,IsoPlayer p,long now){return frame!=null&&admitsScene(frame.scene,p,now);}
 public static synchronized boolean admitsScene(Object scene,IsoPlayer p,long now){var value=environment;var rig=WorldRigCapture.forScene(scene,now);return context(p,now)&&value!=null&&value.actor==p&&value.epoch==epoch&&now>=value.time&&now-value.time<=250_000_000L&&rig!=null&&rig.actor()==p&&rig.generation()==value.rigGeneration;}
 private static void closeOwned(){if(!closeRequested)return;if(world!=null&&worldOwner==Thread.currentThread()){try{world.close();}finally{world=null;worldOwner=null;actor=null;rigGeneration=-1;closeRequested=false;lastStep=0;}}else if(world==null)closeRequested=false;}
 private static void retire(String why){processedFrame=null;processedInput=null;processedReceipt=Long.MIN_VALUE;processedEpoch=-1;processedExternal=-1;leases.clear();packLeases.clear();continuations.clear();HeldContactExternal.clear();HeldContactCapture.clear();closeRequested=true;try{closeOwned();detail=why;}catch(RuntimeException|LinkageError failure){enabled=false;epoch++;environment=null;nextEnvironment=0;WorldRigCapture.requestHeldContacts(false);detail="Held contacts disabled after cleanup failure";}}
 public static synchronized void tick(){if(!enabled)return;if(!needsSimulation()){environment=null;retire("Held feedback and visual constraint inactive");return;}long now=System.nanoTime();var p=player();if(!context(p,now)){environment=null;retire("Held contacts waiting for active tracked single-player prop");return;}if(!HeldContactCapture.prop(p,NativeItems.hand(p,0),0)&&!HeldContactCapture.prop(p,NativeItems.hand(p,1),1)){environment=null;retire("Held contacts waiting for a supported native prop");return;}var rig=WorldRigCapture.latest;if(environment!=null&&environment.actor==p&&environment.rigGeneration==rig.generation()&&environment.epoch==epoch&&now<nextEnvironment)return;try{var geometry=new ArrayList<PhysicalWorld.Static>();int z=(int)Math.floor(p.getZ());for(int dx=-2;dx<=2;dx++)for(int dy=-2;dy<=2;dy++){var square=p.getCell().getGridSquare((int)Math.floor(p.getX())+dx,(int)Math.floor(p.getY())+dy,z);if(square!=null&&square.TreatAsSolidFloor())geometry.add(new PhysicalWorld.Static("heldFloor:"+square.getX()+":"+square.getY()+":"+z,CollisionShape.box(.5f,.5f,.01f,0,0,-.01f),RigidPhysics.pose(square.getX()+.5f,square.getY()+.5f,(float)(z*Math.sqrt(6)))));}geometry.addAll(furniture.sample(p));environment=new Environment(p,rig.generation(),epoch,now,geometry);nextEnvironment=now+100_000_000L;}catch(RuntimeException|LinkageError unavailable){environment=null;retire("Held contact environment unavailable");}}
 public static synchronized void capture(Frame frame){try{captureOwned(frame);}catch(RuntimeException|LinkageError failure){enabled=false;epoch++;environment=null;nextEnvironment=0;retire("Held contacts disabled after capture failure");WorldRigCapture.requestHeldContacts(false);}}
 private static void captureOwned(Frame frame){
  closeOwned();if(!enabled)return;if(!needsSimulation()){retire("Held feedback and visual constraint inactive");return;}
  long now=System.nanoTime();var p=player();var environmentNow=environment;
  if(!context(p,now)||environmentNow==null||environmentNow.actor!=p||environmentNow.epoch!=epoch||now<environmentNow.time||now-environmentNow.time>250_000_000L){retire("Held contacts waiting for fresh world geometry");return;}
  var rig=WorldRigCapture.forScene(frame==null?null:frame.scene,now);
  if(frame==null||rig==null||rig.actor()!=p||rig.generation()!=environmentNow.rigGeneration){retire("Held contacts waiting for matching world rig");return;}
  if(world!=null&&worldOwner!=Thread.currentThread()){detail="Held contacts unavailable on changed capture thread";leases.clear();packLeases.clear();continuations.clear();HeldContactExternal.clear();return;}
  if(closeRequested||actor!=p||rigGeneration!=rig.generation())retire("Held contact generation reset");
  if(processedFrame==frame&&processedInput==Engine.latestInput&&processedEpoch==epoch&&processedReceipt==NativeRig.posedAt&&processedExternal==HeldContactExternal.revision())return;
  try{
   boolean nativePose=NativeRig.posedAt!=0&&now>=NativeRig.posedAt&&now-NativeRig.posedAt<=150_000_000L&&rig.hostTime()>=NativeRig.posedAt;
   var samples=nativePose?HeldContactCapture.capture(frame,p):List.<HeldContactCapture.Sample>of();
   var packs=HeldContactExternal.targets(frame,p,now);
   boolean continuing=continuations.entrySet().stream().anyMatch(entry->continued(entry.getKey(),entry.getValue(),p,rig,now));
   if(samples.isEmpty()&&packs.isEmpty()&&!continuing){retire("Held contact requires one current native or captured pack prop");return;}
   if(world==null){var origin=rig.camera();world=factory.create(origin.x(),origin.y(),origin.height());worldOwner=Thread.currentThread();actor=p;rigGeneration=rig.generation();}
   world.environment(environmentNow.values);var live=new ArrayList<InventoryItem>();var next=new IdentityHashMap<InventoryItem,Lease>();var nextPacks=new IdentityHashMap<InventoryItem,PackLease>();boolean[] occupied=new boolean[2];
   for(var sample:samples){
    if(!HeldContactCapture.current(sample,System.nanoTime())||occupied[sample.side()])continue;occupied[sample.side()]=true;
    var old=leases.get(sample.item());boolean same=old!=null&&old.sample.instance()==sample.instance()&&old.sample.geometry()==sample.geometry()&&old.sample.side()==sample.side()&&old.sample.units()==sample.units()&&HeldContactGeometry.sameMount(old.shape,sample.shape(),sample.units());var shape=same?old.shape:sample.shape();
    if(!same&&old!=null){var retained=new ArrayList<InventoryItem>();retained.addAll(leases.keySet());retained.addAll(packLeases.keySet());retained.addAll(continuations.keySet());retained.removeIf(v->v==sample.item());world.retain(retained);}
    if(world.target(sample.item(),shape,sample.target(),sample.mass()))live.add(sample.item());next.put(sample.item(),new Lease(sample,shape,null));
   }
   for(var candidate:packs){var target=candidate;if(occupied[target.side()]||live.contains(target.item())||!HeldContactExternal.current(candidate,System.nanoTime()))continue;occupied[target.side()]=true;var prior=continuations.get(target.item());boolean same=prior!=null&&prior.source==target.source()&&prior.geometry==target.geometryIdentity()&&prior.sourceEpoch==target.sourceEpoch()&&prior.side==target.side()&&prior.units==target.units()&&HeldContactGeometry.sameMount(prior.shape,target.shape(),target.units());var shape=same?prior.shape:target.shape();if(!same&&prior!=null){var retained=new ArrayList<InventoryItem>();retained.addAll(leases.keySet());retained.addAll(packLeases.keySet());retained.addAll(continuations.keySet());retained.removeIf(v->v==target.item());world.retain(retained);}if(world.target(target.item(),shape,target.pose(),target.mass()))live.add(target.item());nextPacks.put(target.item(),new PackLease(candidate,null));if(target.source()!=HeldContactPack.source())continuations.put(target.item(),new Continuation(target.source(),HeldContactExternal.version(target.source()),new WeakReference<>(p),new WeakReference<>(p.getCell()),target.side(),target.rigGeneration(),target.sourceEpoch(),target.time(),target.units(),target.mass(),target.geometryIdentity(),shape));}
   for(var iterator=continuations.entrySet().iterator();iterator.hasNext();){var entry=iterator.next();if(!continued(entry.getKey(),entry.getValue(),p,rig,now)){iterator.remove();continue;}if(!occupied[entry.getValue().side]&&!live.contains(entry.getKey()))live.add(entry.getKey());}
   world.retain(live);if(lastStep==0)lastStep=now;int steps=0;while(now-lastStep>=8_333_333L&&steps<3){world.step();lastStep+=8_333_333L;steps++;}
   if(now-lastStep>100_000_000L){retire("Held contacts reset after frame gap");return;}
   for(var entry:next.entrySet())entry.setValue(new Lease(entry.getValue().sample,entry.getValue().shape,world.response(entry.getKey())));
   for(var entry:nextPacks.entrySet())entry.setValue(new PackLease(entry.getValue().offer,world.response(entry.getKey())));
   leases.clear();leases.putAll(next);packLeases.clear();packLeases.putAll(nextPacks);processedFrame=frame;processedInput=Engine.latestInput;processedReceipt=NativeRig.posedAt;processedEpoch=epoch;processedExternal=HeldContactExternal.revision();
   detail=leases.values().stream().noneMatch(v->v.response!=null)&&packLeases.values().stream().noneMatch(v->v.response!=null)?"Held rigid mesh preparation pending":"Held prop contacts ready";
   for(var lease:leases.values())if(HeldContactCapture.current(lease.sample,System.nanoTime()))pulse(lease.sample.side(),lease.sample.units(),lease.response,now);
   for(var lease:packLeases.values())if(HeldContactExternal.current(lease.offer,System.nanoTime())){var target=lease.offer;if(visual)HeldContactExternal.constrain(lease.offer,lease.response,maximum);pulse(target.side(),target.units(),lease.response,now,HeldContactPack.angle(lease.response));}
  }catch(RuntimeException|LinkageError unavailable){retire("Held rigid contact unavailable: "+unavailable.getMessage());}
 }
 private static void pulse(int side,double units,HeldContactWorld.Response response,long now){pulse(side,units,response,now,0);}
 private static void pulse(int side,double units,HeldContactWorld.Response response,long now,double angle){if(response==null||!Double.isFinite(response.distance())||response.distance()<.008*units&&angle<Math.toRadians(2))return;detail="Held prop contact "+(side==0?"L":"R")+": "+Math.round(response.distance()/units*1000)+" mm, "+Math.round(Math.toDegrees(angle))+" degrees against captured world";if(intensity>0&&(lastPulse==0||now-lastPulse>=Math.min(5_000_000_000L,(long)(250_000_000L/intensity)))&&Engine.settings!=null&&Engine.settings.haptics&&Engine.hapticRequest<0){Engine.hapticRequest=side;lastPulse=now;}}
 private static boolean continued(InventoryItem item,Continuation value,IsoPlayer p,WorldRigFrame rig,long now){var raw=Engine.latestInput==null?null:value.side==0?Engine.latestInput.left():Engine.latestInput.right();return value.actor.get()==p&&value.cell.get()==p.getCell()&&HeldContactExternal.version(value.source)==value.version&&value.version>=0&&now>=value.time&&now-value.time<=150_000_000L&&rig.generation()==value.rigGeneration&&rig.hand(value.side)!=null&&Math.abs(rig.hand(value.side).units()-value.units)<.0001&&raw!=null&&raw.tracked()&&raw.grip()!=null&&HeldContactCapture.prop(p,item,value.side)&&Float.isFinite(item.getActualWeight())&&Math.max(.01f,item.getActualWeight())==value.mass;}
 /** Release an expired native frame/drawer receipt; the private body keeps only bounded numeric continuity. */
 public static synchronized void finishExternal(HeldContactExternal.Source source,Object scene){packLeases.entrySet().removeIf(entry->entry.getValue().offer.source()==source&&entry.getValue().offer.scene()==scene);}
 public static synchronized HeldContactWorld.Response packResponse(int side){if(worldOwner!=Thread.currentThread())return null;for(var lease:packLeases.values())if(lease.offer.source()==HeldContactPack.source()&&lease.offer.side()==side&&context(lease.offer.actor(),System.nanoTime())&&HeldContactExternal.current(lease.offer,System.nanoTime()))return lease.response;return null;}
 public static synchronized HeldContactWorld.Response response(int side){if(worldOwner!=Thread.currentThread())return null;long now=System.nanoTime();for(var lease:leases.values())if(lease.sample.side()==side&&context(lease.sample.actor(),now)&&HeldContactCapture.current(lease.sample,now))return lease.response;return null;}
 static synchronized List<HeldContactCapture.Sample> samples(){return leases.values().stream().map(Lease::sample).toList();}static synchronized void visualStatus(String value){detail=value;}
 static synchronized void factoryForTest(Factory value){if(enabled||world!=null)throw new IllegalStateException("Held test transport requires Off");factory=Objects.requireNonNull(value);}
 private HeldContactDriver(){}
}
